18	#[derive(Debug, thiserror::Error)]
19	pub enum KeychainError {
20	    #[error("keychain error: {0}")]
21	    Security(#[from] security_framework::base::Error),
22	    /// Returned by the in-memory test store when an item is not found.
23	    #[cfg(test)]
