66	/// Returns true if the error is errSecItemNotFound (OS status -25300).
67	/// Use this to distinguish "item does not exist" from transient OS errors.
68	pub fn is_not_found(err: &KeychainError) -> bool {
69	    match err {
70	        KeychainError::Security(e) => e.code() == -25300,
71	        #[cfg(test)]
72	        KeychainError::NotFound => true,
