84	/// Store the DPoP private key scalar (32 bytes) in the Keychain.
85	pub fn store_dpop_key(private_bytes: &[u8]) -> Result<(), KeychainError> {
86	    store_item(DPOP_KEY_PRIV_ACCOUNT, private_bytes)
87	}
