89	/// Load the DPoP private key scalar from the Keychain.
90	///
91	/// Returns `None` if no key has been stored yet (first run).
92	/// The returned bytes are wrapped in `Zeroizing` to ensure they are cleared on drop.
93	pub fn load_dpop_key() -> Option<zeroize::Zeroizing<[u8; 32]>> {
94	    match get_item(DPOP_KEY_PRIV_ACCOUNT) {
95	        Ok(bytes) if bytes.len() == 32 => {
96	            let mut arr = [0u8; 32];
97	            arr.copy_from_slice(&bytes);
98	            Some(zeroize::Zeroizing::new(arr))
99	        }
100	        Ok(_) => {
101	            tracing::warn!("DPoP key in Keychain has unexpected length; treating as absent");
102	            None
103	        }
104	        Err(e) if is_not_found(&e) => None,
105	        Err(e) => {
106	            tracing::error!(error = ?e, "Keychain error loading DPoP key");
107	            None
108	        }
109	    }
110	}
