112	/// Store the OAuth access token and refresh token in the Keychain.
113	pub fn store_oauth_tokens(access_token: &str, refresh_token: &str) -> Result<(), KeychainError> {
114	    store_item(OAUTH_ACCESS_TOKEN_ACCOUNT, access_token.as_bytes())?;
115	    store_item(OAUTH_REFRESH_TOKEN_ACCOUNT, refresh_token.as_bytes())?;
116	    Ok(())
117	}
118	
119	/// Load the OAuth access token and refresh token from the Keychain.
120	///
121	/// Returns `None` if either token is missing (not yet authenticated).
122	pub fn load_oauth_tokens() -> Option<(String, String)> {
123	    let access = match get_item(OAUTH_ACCESS_TOKEN_ACCOUNT) {
124	        Ok(b) => match String::from_utf8(b) {
125	            Ok(s) => s,
126	            Err(e) => {
127	                tracing::error!(error = ?e, "UTF-8 error decoding access token from Keychain");
128	                return None;
129	            }
130	        },
131	        Err(e) if is_not_found(&e) => return None,
132	        Err(e) => {
133	            tracing::error!(error = ?e, "Keychain error loading access token");
134	            return None;
135	        }
136	    };
137	    let refresh = match get_item(OAUTH_REFRESH_TOKEN_ACCOUNT) {
138	        Ok(b) => match String::from_utf8(b) {
139	            Ok(s) => s,
140	            Err(e) => {
141	                tracing::error!(error = ?e, "UTF-8 error decoding refresh token from Keychain");
142	                return None;
143	            }
144	        },
145	        Err(e) if is_not_found(&e) => return None,
146	        Err(e) => {
147	            tracing::error!(error = ?e, "Keychain error loading refresh token");
148	            return None;
149	        }
150	    };
151	    Some((access, refresh))
152	}
