229	/// In-memory Keychain substitute used exclusively in test builds.
230	///
231	/// Thread-local storage ensures tests on different threads are fully isolated.
232	/// Call `clear_for_test()` at the start of each test to handle sequential
233	/// reuse of the same OS thread by the Rust test harness.
234	#[cfg(test)]
235	mod test_store {
236	    use std::cell::RefCell;
237	    use std::collections::HashMap;
238	
239	    thread_local! {
240	        static STORE: RefCell<HashMap<String, Vec<u8>>> = RefCell::new(HashMap::new());
241	    }
242	
243	    pub fn get(account: &str) -> Option<Vec<u8>> {
244	        STORE.with(|s| s.borrow().get(account).cloned())
245	    }
246	
247	    pub fn set(account: &str, data: Vec<u8>) {
248	        STORE.with(|s| {
249	            s.borrow_mut().insert(account.to_string(), data);
250	        });
251	    }
252	
253	    pub fn delete(account: &str) {
254	        STORE.with(|s| {
255	            s.borrow_mut().remove(account);
256	        });
257	    }
258	
259	    pub fn clear_all() {
260	        STORE.with(|s| s.borrow_mut().clear());
261	    }
262	}
